/* generated by scripts/build_academy.mjs from content/academy/ui/<lang>.json and the glossary — texts of docs/shared/sims.js (all 11 ClayArena languages; English where a translation is missing) and the names of the terms the animations show. Do not edit. */
window.CLAYSIMS_TEXT = {"en":{"launch":"Launch","method":"Method","speed":"Target speed","distance":"Distance","demo":"Watch the method","try":"Your turn: press when you would shoot","shoot":"Shoot","hit":"Hit! The target breaks.","behind":"Behind — the shot passed behind the target","ahead":"In front — the shot passed ahead of the target","perceived":"Lead you see at the decision","actual":"Actual lead at the shot","lab_note":"Slow motion, simplified physics for teaching. The shot slows down as it flies: on average about 330 m/s over 15 m, 300 m/s over 25 m and 255 m/s over 40 m (it leaves the barrel at about 360–430 m/s). It takes about 0.15 s from the decision to the shot (an average estimate). The ring marks the part of the pattern dense enough to break the target: a radius of about 33 cm at 15 m and 45 cm at 40 m. The muzzle is about 1 m from the eye. Distances along the target's line, the lead and the ring are to scale; the target is drawn larger than life so you can see it (about to scale where the lead is counted in target widths). The actual lead depends on the target's speed, distance and angle, the cartridge and the shooter.","unit_m":"m","unit_ft":"ft","unit_ms":"m/s","pair_report":"{term}: the 2nd target is released at the sound of the 1st shot","pair_sim":"{term}: both targets are released together","pair_rafale":"{term}: the 2nd target from the same trap, as soon as the trap has reloaded","listen":"Listen","no_shot":"No shot fired.","at_muzzle":"seen at the muzzle","compare":"Same target, four methods: the actual lead is the same, the lead you see is not","how_maintained":"The muzzles wait in front and the target closes the gap. Press Shoot when the gap looks right: the gun then moves at the target's speed and holds that lead.","how_swing":"The muzzles start behind the target and move faster than it. Press Shoot as the muzzles pass the front of the target: the gun keeps gaining during the delay, so the actual lead is bigger.","how_pullaway":"The muzzles move with the target first, then accelerate ahead. Press Shoot while the gun is still accelerating: the lead you see is smaller than the actual lead.","how_ambush":"The muzzles wait still at a point ahead. Press Shoot before the target reaches that point: the shot needs time, so a shot fired as the target arrives goes behind.","stop_gun":"Stop the gun at the trigger (a fault)","clay_widths":"target widths","unit_cm":"cm","unit_in":"in","anim_play":"Play","anim_replay":"Replay","anim_slow":"Slow motion","anim_marker":"with animation","anim_h_flight":"Watch how the target flies","anim_h_points":"Watch the three points","anim_h_eyes":"Watch where the eyes look","anim_h_stance":"Watch the stance","anim_h_pair":"Watch how a double is thrown","anim_h_lead":"Watch how the lead works","anim_h_mount":"Watch the gun mount","anim_h_follow":"Watch the follow-through","anim_h_call":"Watch the call and the release","anim_h_gunpos":"Watch the gun position","anim_h_misfire":"Watch what to do after a misfire","anim_w_flight":"Follow the whole flight: where the target comes from, where you see it clearly and where it goes.","anim_w_points":"The eyes wait at the pick-up point, the muzzles at the hold point; the target breaks at the break point.","anim_w_eyes":"Soft focus around the pick-up point, then hard focus on the front edge of the target.","anim_w_stance":"The front foot points at the break point; the body turns back to the hold point.","anim_w_pair":"Watch when the second target leaves: after the shot, together with the first, or from the same trap.","anim_w_lead":"Watch the gap between the muzzles and the target at the moment of the shot, then try it yourself.","anim_w_mount":"The muzzles move with the target first; the mount is finished as the shot comes.","anim_w_follow":"The gun keeps moving after the shot; stop it at the trigger and the shot goes behind.","anim_w_call":"The clock shows when the target leaves after the call or the referee's signal; a late target is a No Bird.","anim_w_gunpos":"In Sporting™ the stock stays below the line on the vest until the target appears.","anim_w_misfire":"After a misfire, stay put: gun closed and pointing down the range until the referee has checked it.","anim_unit_s":"s","anim_after_call":"after the call","anim_after_signal":"after the signal","anim_t_signal":"Sporting™: referee's signal","anim_t_late":"Late target","anim_t_manual":"Compak® Sporting: by hand","anim_t_sonopull":"Compak® Sporting: {term}","anim_t_early":"Gun up at the call","anim_s_in_time":"The target leaves {n} s after the signal: in time (the limit is {max} s).","anim_s_late":"The target leaves {n} s after the signal, later than {max} s: the referee calls “No Bird” and the target is thrown again.","anim_s_manual":"Released by hand: the target leaves {n} s after the call (allowed: 0 to {max} s).","anim_s_sonopull":"Sonopull: the microphone hears the call and the target leaves {n} s later, every time.","anim_s_gun_low":"Ready position: the stock touches the body below the line on the vest.","anim_s_gun_mount":"The target has appeared: only now does the gun come up to the shoulder.","anim_s_early":"Called with the gun already at the shoulder: the first time, a spoken warning and a yellow card.","anim_s_click":"Click: the gun did not fire.","anim_s_hold":"Stay where you are: gun closed and pointing down the range; do not open it or touch the safety.","anim_s_ref":"The referee examines the gun.","anim_s_repeat":"First malfunction of the round: the target is thrown again.","anim_stop":"Stop","anim_s_mount_ready":"Ready: the gun is low and the eyes wait for the target.","anim_s_move":"Move: the front hand starts the muzzles along the target's line.","anim_s_mount":"Mount: the stock comes up to the cheek and into the shoulder; the head stays still.","anim_s_shoot":"Shoot: the mount is finished as the shot comes.","anim_scale":"Only the shooter and the stand are to scale; the field and the target's flight are shortened.","anim_cheek":"cheek on the comb","anim_l_foot":"front foot","anim_l_body":"body"},"uk":{"launch":"Запустити","method":"Метод","speed":"Швидкість мішені","distance":"Відстань","demo":"Показати метод","try":"Ваша черга: натисніть, коли стріляли б","shoot":"Постріл","hit":"Влучання! Мішень розбита.","behind":"Позаду — дріб пройшов позаду мішені","ahead":"Попереду — дріб пройшов попереду мішені","perceived":"Винос, який ви бачите в момент рішення","actual":"Фактичний винос у момент пострілу","lab_note":"Уповільнено, спрощена фізика для навчання. Дріб у польоті сповільнюється: у середньому близько 330 м/с на відстані 15 м, 300 м/с — на 25 м і 255 м/с — на 40 м (зі ствола він вилітає зі швидкістю близько 360–430 м/с). Від рішення до пострілу минає близько 0,15 с (усереднена оцінка). Кільце позначає ту частину осипу, яка досить густа, щоб розбити мішень: радіус близько 33 см на 15 м і 45 см на 40 м. Дульний зріз — приблизно за 1 м від ока. Відстані вздовж лінії польоту, винос і кільце показано в масштабі; мішень намальовано більшою, ніж насправді, щоб її було видно (приблизно в масштабі — там, де винос рахують у ширинах мішені). Фактичний винос залежить від швидкості, відстані й кута мішені, від набою та стрільця.","unit_m":"м","unit_ft":"фт","unit_ms":"м/с","pair_report":"{term}: друга мішень вилітає на звук першого пострілу","pair_sim":"{term}: обидві мішені вилітають разом","pair_rafale":"{term}: друга мішень з тієї ж машинки, щойно машинка перезарядиться","listen":"Прослухати","no_shot":"Пострілу не було.","at_muzzle":"біля дульного зрізу","compare":"Та сама мішень, чотири методи: фактичний винос однаковий, видимий — різний","how_maintained":"Стволи чекають попереду, і мішень наближається до них. Натисніть «Постріл», коли винос виглядає правильним: далі рушниця йде зі швидкістю мішені й тримає цей винос.","how_swing":"Стволи стартують позаду мішені й рухаються швидше за неї. Натисніть «Постріл», коли стволи проходять передній край мішені: за час затримки рушниця ще випереджає мішень, тому фактичний винос більший.","how_pullaway":"Стволи спершу йдуть разом із мішенню, потім прискорюються вперед. Натисніть «Постріл», поки рушниця ще прискорюється: видимий винос менший за фактичний.","how_ambush":"Стволи нерухомо чекають у точці попереду. Натисніть «Постріл» раніше, ніж мішень дійде до цієї точки: дробу потрібен час, тому постріл у мить, коли мішень уже в точці, іде позаду.","stop_gun":"Зупинити рушницю на спуску (помилка)","clay_widths":"ширин мішені","unit_cm":"см","unit_in":"дюйм.","anim_play":"Відтворити","anim_replay":"Ще раз","anim_slow":"Уповільнено","anim_marker":"з анімацією","anim_h_flight":"Подивіться, як летить мішень","anim_h_points":"Подивіться на три точки","anim_h_eyes":"Подивіться, куди дивляться очі","anim_h_stance":"Подивіться на стійку","anim_h_pair":"Подивіться, як подають дуплет","anim_h_lead":"Подивіться, як працює винос","anim_h_mount":"Подивіться на вкладку","anim_h_follow":"Подивіться на продовження руху","anim_h_call":"Подивіться на команду й виліт мішені","anim_h_gunpos":"Подивіться на положення рушниці","anim_h_misfire":"Подивіться, що робити після осічки","anim_w_flight":"Простежте всю траєкторію: звідки летить мішень, де її добре видно і куди вона йде.","anim_w_points":"Очі чекають у точці підхоплення, стволи — у точці утримання; мішень розбивається в точці пострілу.","anim_w_eyes":"М’який фокус навколо точки підхоплення, потім жорсткий фокус на передньому краї мішені.","anim_w_stance":"Носок передньої ноги дивиться на точку пострілу, а корпус повертається назад до точки утримання.","anim_w_pair":"Дивіться, коли вилітає друга мішень: після пострілу, разом із першою чи з тієї самої машинки.","anim_w_lead":"Дивіться на проміжок між стволами й мішенню в мить пострілу, а потім спробуйте самі.","anim_w_mount":"Спершу стволи рушають за мішенню, а вкладка завершується разом із пострілом.","anim_w_follow":"Рушниця рухається й після пострілу; зупиніть її на спуску — і дріб піде позаду.","anim_w_call":"Годинник показує, коли вилітає мішень після команди чи сигналу судді; запізніла мішень — No Bird.","anim_w_gunpos":"У Sporting™ приклад лишається нижче лінії на жилеті, доки не з’явиться мішень.","anim_w_misfire":"Після осічки стійте на місці: рушниця закрита й спрямована в бік поля, доки суддя її не огляне.","anim_unit_s":"с","anim_after_call":"після команди","anim_after_signal":"після сигналу","anim_t_signal":"Sporting™: сигнал судді","anim_t_late":"Запізніла мішень","anim_t_manual":"Compak® Sporting: вручну","anim_t_sonopull":"Compak® Sporting: {term}","anim_t_early":"Рушниця вже вгорі на команді","anim_s_in_time":"Мішень вилітає через {n} с після сигналу: вчасно (межа — {max} с).","anim_s_late":"Мішень вилітає через {n} с після сигналу, пізніше ніж за {max} с: суддя оголошує «No Bird», і мішень запускають знову.","anim_s_manual":"Ручний запуск: мішень вилітає через {n} с після команди (дозволено від 0 до {max} с).","anim_s_sonopull":"Сонопул: мікрофон чує команду, і мішень вилітає через {n} с — щоразу однаково.","anim_s_gun_low":"Вихідне положення: приклад торкається тіла нижче лінії на жилеті.","anim_s_gun_mount":"Мішень з’явилася: лише тепер рушницю вкладають у плече.","anim_s_early":"Команда з уже вкладеною рушницею: уперше — усне попередження й жовта картка.","anim_s_click":"Клац: рушниця не вистрілила.","anim_s_hold":"Стійте на місці: рушниця закрита й спрямована в бік поля; не відкривайте її й не торкайтеся запобіжника.","anim_s_ref":"Суддя оглядає рушницю.","anim_s_repeat":"Перша несправність у серії: мішень запускають знову.","anim_stop":"Зупинити","anim_s_mount_ready":"Готовність: рушниця внизу, очі чекають на мішень.","anim_s_move":"Рух: передня рука веде стволи вздовж лінії мішені.","anim_s_mount":"Вкладка: приклад піднімається до щоки й лягає в плече; голова нерухома.","anim_s_shoot":"Постріл: вкладка завершується разом із пострілом.","anim_scale":"У масштабі лише стрілець і стрілецьке місце; поле й політ мішені скорочено.","anim_cheek":"щока на гребені","anim_l_foot":"передня нога","anim_l_body":"корпус"},"de":{"launch":"Werfen","method":"Methode","speed":"Geschwindigkeit der Scheibe","distance":"Entfernung","demo":"Methode ansehen","try":"Sie sind dran: Drücken Sie, wenn Sie schießen würden","shoot":"Schuss","hit":"Treffer! Die Scheibe bricht.","behind":"Dahinter – der Schuss ging hinter der Scheibe vorbei","ahead":"Davor – der Schuss ging vor der Scheibe vorbei","perceived":"Vorhalt, den Sie bei der Entscheidung sehen","actual":"Tatsächlicher Vorhalt beim Schuss","lab_note":"Zeitlupe und vereinfachte Physik zum Lernen. Der Schrot wird im Flug langsamer: im Mittel etwa 330 m/s auf 15 m, 300 m/s auf 25 m und 255 m/s auf 40 m (er verlässt den Lauf mit etwa 360–430 m/s). Von der Entscheidung bis zum Schuss vergehen etwa 0,15 s (ein geschätzter Mittelwert). Der Ring zeigt den Teil der Schrotgarbe, der dicht genug ist, um die Scheibe zu zerbrechen: ein Radius von etwa 33 cm auf 15 m und 45 cm auf 40 m. Die Mündung ist etwa 1 m vom Auge entfernt. Entfernungen entlang der Flugbahn der Scheibe, Vorhalt und Ring sind maßstabsgetreu; die Scheibe ist größer gezeichnet, als sie ist, damit man sie sieht (annähernd maßstabsgetreu dort, wo der Vorhalt in Scheibenbreiten gezählt wird). Der tatsächliche Vorhalt hängt von Geschwindigkeit, Entfernung und Winkel der Scheibe, von der Patrone und vom Schützen ab.","unit_m":"m","unit_ft":"ft","unit_ms":"m/s","pair_report":"{term}: Die 2. Scheibe wird auf den Knall des 1. Schusses ausgelöst","pair_sim":"{term}: Beide Scheiben werden gleichzeitig ausgelöst","pair_rafale":"{term}: Die 2. Scheibe aus derselben Maschine, sobald diese nachgeladen hat","listen":"Anhören","no_shot":"Kein Schuss abgegeben.","at_muzzle":"an der Mündung gesehen","compare":"Dieselbe Scheibe, vier Methoden: Der tatsächliche Vorhalt ist gleich, der sichtbare nicht","how_maintained":"Die Läufe warten vor der Scheibe, die Scheibe kommt näher. Drücken Sie „Schuss“, wenn der Abstand richtig aussieht: Dann bewegt sich die Flinte mit der Geschwindigkeit der Scheibe und hält diesen Vorhalt.","how_swing":"Die Läufe starten hinter der Scheibe und sind schneller als sie. Drücken Sie „Schuss“, wenn die Läufe die Vorderkante der Scheibe passieren: Während der Verzögerung gewinnt die Flinte weiter, deshalb ist der tatsächliche Vorhalt größer.","how_pullaway":"Die Läufe gehen zuerst mit der Scheibe mit und beschleunigen dann nach vorn. Drücken Sie „Schuss“, solange die Flinte noch beschleunigt: Der sichtbare Vorhalt ist kleiner als der tatsächliche.","how_ambush":"Die Läufe warten still an einem Punkt vor der Scheibe. Drücken Sie „Schuss“, bevor die Scheibe diesen Punkt erreicht: Der Schrot braucht Zeit, ein Schuss erst beim Eintreffen der Scheibe geht dahinter.","stop_gun":"Flinte beim Abziehen anhalten (Fehler)","clay_widths":"Scheibenbreiten","unit_cm":"cm","unit_in":"Zoll","anim_play":"Abspielen","anim_replay":"Noch einmal","anim_slow":"Zeitlupe","anim_marker":"mit Animation","anim_h_flight":"Sehen Sie, wie die Scheibe fliegt","anim_h_points":"Sehen Sie die drei Punkte","anim_h_eyes":"Sehen Sie, wohin die Augen schauen","anim_h_stance":"Sehen Sie sich die Fußstellung an","anim_h_pair":"Sehen Sie, wie eine Doublette geworfen wird","anim_h_lead":"Sehen Sie, wie der Vorhalt funktioniert","anim_h_mount":"Sehen Sie sich den Anschlag an","anim_h_follow":"Sehen Sie sich das Nachschwingen an","anim_h_call":"Sehen Sie Abruf und Start der Scheibe","anim_h_gunpos":"Sehen Sie sich die Haltung der Flinte an","anim_h_misfire":"Sehen Sie, was nach einem Versager zu tun ist","anim_w_flight":"Verfolgen Sie den ganzen Flug: woher die Scheibe kommt, wo Sie sie gut sehen und wohin sie fliegt.","anim_w_points":"Die Augen warten am Augenaufnahmepunkt, die Läufe am Waffenhaltepunkt; die Scheibe bricht in der Trefferzone.","anim_w_eyes":"Weicher Fokus um den Augenaufnahmepunkt, dann harter Fokus auf die Vorderkante der Scheibe.","anim_w_stance":"Der vordere Fuß zeigt zur Trefferzone; der Oberkörper dreht zurück zum Waffenhaltepunkt.","anim_w_pair":"Achten Sie darauf, wann die zweite Scheibe startet: nach dem Schuss, zusammen mit der ersten oder aus derselben Maschine.","anim_w_lead":"Achten Sie auf den Abstand zwischen Läufen und Scheibe im Moment des Schusses und versuchen Sie es dann selbst.","anim_w_mount":"Zuerst gehen die Läufe mit der Scheibe mit; der Anschlag ist erst mit dem Schuss fertig.","anim_w_follow":"Die Flinte bewegt sich nach dem Schuss weiter; halten Sie sie beim Abziehen an, geht der Schuss dahinter.","anim_w_call":"Die Uhr zeigt, wann die Scheibe nach dem Abruf oder dem Signal des Schiedsrichters startet; eine verspätete Scheibe ist ein No Bird.","anim_w_gunpos":"Im Sporting™ bleibt der Schaft unter der Westenmarkierung, bis die Scheibe erscheint.","anim_w_misfire":"Nach einem Versager bleiben Sie stehen: Flinte geschlossen und Richtung Schussfeld, bis der Schiedsrichter sie geprüft hat.","anim_unit_s":"s","anim_after_call":"nach dem Abruf","anim_after_signal":"nach dem Signal","anim_t_signal":"Sporting™: Signal des Schiedsrichters","anim_t_late":"Verspätete Scheibe","anim_t_manual":"Compak® Sporting: von Hand","anim_t_sonopull":"Compak® Sporting: {term}","anim_t_early":"Flinte beim Abruf schon oben","anim_s_in_time":"Die Scheibe startet {n} s nach dem Signal: rechtzeitig (die Grenze liegt bei {max} s).","anim_s_late":"Die Scheibe startet {n} s nach dem Signal, später als {max} s: Der Schiedsrichter ruft „No Bird“, und die Scheibe wird neu geworfen.","anim_s_manual":"Auslösung von Hand: Die Scheibe startet {n} s nach dem Abruf (erlaubt: 0 bis {max} s).","anim_s_sonopull":"Sonopull: Das Mikrofon hört den Abruf, und die Scheibe startet jedes Mal {n} s später.","anim_s_gun_low":"Jagdanschlag: Der Schaft berührt den Körper unterhalb der Westenmarkierung.","anim_s_gun_mount":"Die Scheibe ist zu sehen: Erst jetzt kommt die Flinte an die Schulter.","anim_s_early":"Abruf mit bereits angeschlagener Flinte: beim ersten Mal eine mündliche Verwarnung und die Gelbe Karte.","anim_s_click":"Klick: Die Flinte hat nicht geschossen.","anim_s_hold":"Bleiben Sie stehen: Flinte geschlossen und Richtung Schussfeld; nicht öffnen und die Sicherung nicht berühren.","anim_s_ref":"Der Schiedsrichter prüft die Flinte.","anim_s_repeat":"Erste Funktionsstörung der Runde: Die Scheibe wird neu geworfen.","anim_stop":"Stopp","anim_s_mount_ready":"Bereit: Die Flinte ist unten, die Augen warten auf die Scheibe.","anim_s_move":"Bewegen: Die vordere Hand führt die Läufe auf die Flugbahn der Scheibe.","anim_s_mount":"Anschlag: Der Schaft kommt an die Wange und in die Schulter; der Kopf bleibt ruhig.","anim_s_shoot":"Schießen: Der Anschlag ist erst mit dem Schuss fertig.","anim_scale":"Nur der Schütze und der Standplatz sind maßstabsgetreu; das Feld und die Flugbahn der Scheibe sind verkürzt.","anim_cheek":"Wange am Schaftrücken","anim_l_foot":"vorderer Fuß","anim_l_body":"Oberkörper"},"fr":{"launch":"Lancer","method":"Méthode","speed":"Vitesse du plateau","distance":"Distance","demo":"Voir la méthode","try":"À vous : appuyez au moment où vous tireriez","shoot":"Tirer","hit":"Touché ! Le plateau est cassé.","behind":"Derrière : la gerbe est passée derrière le plateau","ahead":"Devant : la gerbe est passée devant le plateau","perceived":"Avance perçue au moment de la décision","actual":"Avance réelle au moment du tir","lab_note":"Ralenti et physique simplifiée pour l'apprentissage. Les plombs ralentissent en vol : en moyenne environ 330 m/s sur 15 m, 300 m/s sur 25 m et 255 m/s sur 40 m (ils quittent le canon à environ 360–430 m/s). Il faut environ 0,15 s entre la décision et le coup (une estimation moyenne). L'anneau marque la partie de la gerbe assez dense pour casser le plateau : un rayon d'environ 33 cm à 15 m et 45 cm à 40 m. La bouche du canon est à environ 1 m de l'œil. Les distances le long de la trajectoire du plateau, l'avance et l'anneau sont à l'échelle ; le plateau est dessiné plus grand que nature pour qu'on le voie (à peu près à l'échelle là où l'avance se compte en largeurs de plateau). L'avance réelle dépend de la vitesse, de la distance et de l'angle du plateau, de la cartouche et du tireur.","unit_m":"m","unit_ft":"ft","unit_ms":"m/s","pair_report":"{term} : le 2e plateau part au bruit du 1er coup","pair_sim":"{term} : les deux plateaux partent ensemble","pair_rafale":"{term} : le 2e plateau part du même lanceur dès que celui-ci est réarmé","listen":"Écouter","no_shot":"Aucun tir.","at_muzzle":"vu à la bouche du canon","compare":"Même plateau, quatre méthodes : l'avance réelle est la même, l'avance perçue non","how_maintained":"Les canons attendent devant le plateau, qui se rapproche. Appuyez sur « Tirer » quand l'écart paraît juste : le fusil suit alors à la vitesse du plateau et garde cette avance.","how_swing":"Les canons partent derrière le plateau et vont plus vite que lui. Appuyez sur « Tirer » quand les canons passent l'avant du plateau : pendant le délai, le fusil gagne encore du terrain, donc l'avance réelle est plus grande.","how_pullaway":"Les canons suivent d'abord le plateau, puis accélèrent devant lui. Appuyez sur « Tirer » pendant que le fusil accélère encore : l'avance perçue est plus petite que l'avance réelle.","how_ambush":"Les canons attendent immobiles en un point devant le plateau. Appuyez sur « Tirer » avant que le plateau n'atteigne ce point : les plombs ont besoin de temps, un tir au moment où le plateau arrive passe derrière.","stop_gun":"Arrêter le fusil au départ du coup (erreur)","clay_widths":"largeurs de plateau","unit_cm":"cm","unit_in":"po","anim_play":"Lire","anim_replay":"Revoir","anim_slow":"Ralenti","anim_marker":"avec animation","anim_h_flight":"Regardez comment vole le plateau","anim_h_points":"Regardez les trois points","anim_h_eyes":"Regardez où se pose le regard","anim_h_stance":"Regardez la position des pieds","anim_h_pair":"Regardez comment part un doublé","anim_h_lead":"Regardez comment fonctionne l'avance","anim_h_mount":"Regardez l'épaulé","anim_h_follow":"Regardez l'accompagnement","anim_h_call":"Regardez l'appel et le départ du plateau","anim_h_gunpos":"Regardez la position du fusil","anim_h_misfire":"Regardez quoi faire après un raté","anim_w_flight":"Suivez tout le vol : d'où vient le plateau, où vous le voyez bien et où il va.","anim_w_points":"Les yeux attendent au point de prise, les canons au point d'attente ; le plateau casse au point de casse.","anim_w_eyes":"Regard large autour du point de prise, puis regard focalisé sur le bord avant du plateau.","anim_w_stance":"Le pied avant pointe vers le point de casse ; le buste tourne en arrière vers le point d'attente.","anim_w_pair":"Observez quand part le second plateau : après le coup, en même temps que le premier ou du même lanceur.","anim_w_lead":"Observez l'écart entre les canons et le plateau au moment du coup, puis essayez vous-même.","anim_w_mount":"Les canons suivent d'abord le plateau ; l'épaulé s'achève au moment du coup.","anim_w_follow":"Le fusil continue de bouger après le coup ; arrêtez-le au départ du coup et la gerbe passe derrière.","anim_w_call":"L'horloge montre quand le plateau part après l'appel ou le signal de l'arbitre ; un plateau en retard est un No bird.","anim_w_gunpos":"En Sporting™, la crosse reste sous la ligne de la veste jusqu'à l'apparition du plateau.","anim_w_misfire":"Après un raté, restez en place : fusil fermé et pointé vers la zone de tir jusqu'à ce que l'arbitre l'ait examiné.","anim_unit_s":"s","anim_after_call":"après l'appel","anim_after_signal":"après le signal","anim_t_signal":"Sporting™ : signal de l'arbitre","anim_t_late":"Plateau en retard","anim_t_manual":"Compak® Sporting : à la main","anim_t_sonopull":"Compak® Sporting : {term}","anim_t_early":"Fusil déjà épaulé à l'appel","anim_s_in_time":"Le plateau part {n} s après le signal : à temps (la limite est de {max} s).","anim_s_late":"Le plateau part {n} s après le signal, au-delà de {max} s : l'arbitre annonce « No bird » et le plateau est relancé.","anim_s_manual":"Lancement à la main : le plateau part {n} s après l'appel (autorisé : de 0 à {max} s).","anim_s_sonopull":"Sonopull : le micro entend l'appel et le plateau part {n} s plus tard, à chaque fois.","anim_s_gun_low":"Position d'attente : la crosse touche le corps sous la ligne de la veste.","anim_s_gun_mount":"Le plateau est apparu : c'est seulement maintenant que le fusil monte à l'épaule.","anim_s_early":"Appel avec le fusil déjà épaulé : la première fois, un avertissement oral et un carton jaune.","anim_s_click":"Clic : le coup n'est pas parti.","anim_s_hold":"Restez en place : fusil fermé et pointé vers la zone de tir ; ne l'ouvrez pas et ne touchez pas la sûreté.","anim_s_ref":"L'arbitre examine le fusil.","anim_s_repeat":"Premier incident de la série : le plateau est relancé.","anim_stop":"Arrêter","anim_s_mount_ready":"Prêt : le fusil est bas, les yeux attendent le plateau.","anim_s_move":"Bouger : la main avant lance les canons sur la ligne du plateau.","anim_s_mount":"Épaulé : la crosse monte à la joue et à l'épaule ; la tête reste immobile.","anim_s_shoot":"Tirer : l'épaulé s'achève au moment du coup.","anim_scale":"Seuls le tireur et le poste de tir sont à l'échelle ; le terrain et le vol du plateau sont raccourcis.","anim_cheek":"joue sur le busc","anim_l_foot":"pied avant","anim_l_body":"buste"},"it":{"launch":"Lancia","method":"Metodo","speed":"Velocità del piattello","distance":"Distanza","demo":"Guarda il metodo","try":"Tocca a te: premi quando spareresti","shoot":"Spara","hit":"Colpito! Il piattello si rompe.","behind":"Dietro: la rosata è passata dietro il piattello","ahead":"Davanti: la rosata è passata davanti al piattello","perceived":"Anticipo che vedi al momento della decisione","actual":"Anticipo reale al momento dello sparo","lab_note":"Rallentatore e fisica semplificata a scopo didattico. I pallini rallentano in volo: in media circa 330 m/s su 15 m, 300 m/s su 25 m e 255 m/s su 40 m (escono dalla canna a circa 360–430 m/s). Dalla decisione allo sparo passano circa 0,15 s (una stima media). L'anello indica la parte della rosata abbastanza densa da rompere il piattello: un raggio di circa 33 cm a 15 m e 45 cm a 40 m. La volata è a circa 1 m dall'occhio. Le distanze lungo la traiettoria del piattello, l'anticipo e l'anello sono in scala; il piattello è disegnato più grande del vero perché si veda (all'incirca in scala dove l'anticipo si conta in larghezze di piattello). L'anticipo reale dipende da velocità, distanza e angolo del piattello, dalla cartuccia e dal tiratore.","unit_m":"m","unit_ft":"ft","unit_ms":"m/s","pair_report":"{term}: il 2º piattello parte al rumore del 1º colpo","pair_sim":"{term}: entrambi i piattelli partono insieme","pair_rafale":"{term}: il 2º piattello dalla stessa macchina, appena si è ricaricata","listen":"Ascolta","no_shot":"Nessun colpo sparato.","at_muzzle":"visto alla volata","compare":"Stesso piattello, quattro metodi: l'anticipo reale è uguale, quello che vedi no","how_maintained":"Le canne aspettano davanti al piattello, che si avvicina. Premi «Spara» quando la distanza sembra giusta: il fucile segue allora alla velocità del piattello e mantiene quell'anticipo.","how_swing":"Le canne partono dietro il piattello e sono più veloci di lui. Premi «Spara» quando le canne superano il bordo anteriore del piattello: durante il ritardo il fucile guadagna ancora, quindi l'anticipo reale è maggiore.","how_pullaway":"Le canne prima accompagnano il piattello, poi accelerano in avanti. Premi «Spara» mentre il fucile sta ancora accelerando: l'anticipo che vedi è minore di quello reale.","how_ambush":"Le canne aspettano ferme in un punto davanti al piattello. Premi «Spara» prima che il piattello arrivi in quel punto: i pallini hanno bisogno di tempo, quindi un colpo sparato quando il piattello arriva passa dietro.","stop_gun":"Fermare il fucile allo sparo (errore)","clay_widths":"larghezze di piattello","unit_cm":"cm","unit_in":"pollici","anim_play":"Riproduci","anim_replay":"Rivedi","anim_slow":"Rallentatore","anim_marker":"con animazione","anim_h_flight":"Guarda come vola il piattello","anim_h_points":"Guarda i tre punti","anim_h_eyes":"Guarda dove si posa lo sguardo","anim_h_stance":"Guarda la posizione dei piedi","anim_h_pair":"Guarda come parte un doppio","anim_h_lead":"Guarda come funziona l'anticipo","anim_h_mount":"Guarda l'imbracciata","anim_h_follow":"Guarda l'accompagnamento","anim_h_call":"Guarda la chiamata e la partenza del piattello","anim_h_gunpos":"Guarda la posizione del fucile","anim_h_misfire":"Guarda cosa fare dopo una cilecca","anim_w_flight":"Segui tutto il volo: da dove arriva il piattello, dove lo vedi bene e dove va.","anim_w_points":"Gli occhi aspettano al punto di presa, le canne al punto di attesa; il piattello si rompe al punto di rottura.","anim_w_eyes":"Sguardo morbido intorno al punto di presa, poi sguardo concentrato sul bordo anteriore del piattello.","anim_w_stance":"Il piede avanti punta verso il punto di rottura; il busto ruota indietro verso il punto di attesa.","anim_w_pair":"Guarda quando parte il secondo piattello: dopo lo sparo, insieme al primo o dalla stessa macchina.","anim_w_lead":"Guarda la distanza tra le canne e il piattello al momento dello sparo, poi prova tu.","anim_w_mount":"Prima le canne seguono il piattello; l'imbracciata si completa insieme allo sparo.","anim_w_follow":"Il fucile continua a muoversi dopo lo sparo; se lo fermi allo sparo, la rosata passa dietro.","anim_w_call":"L'orologio mostra quando parte il piattello dopo la chiamata o il segnale dell'arbitro; un piattello in ritardo è un No bird.","anim_w_gunpos":"Nello Sporting™ il calcio resta sotto la linea sul giubbotto finché non appare il piattello.","anim_w_misfire":"Dopo una cilecca resta fermo: fucile chiuso e puntato verso il campo finché l'arbitro non l'ha controllato.","anim_unit_s":"s","anim_after_call":"dopo la chiamata","anim_after_signal":"dopo il segnale","anim_t_signal":"Sporting™: segnale dell'arbitro","anim_t_late":"Piattello in ritardo","anim_t_manual":"Compak® Sporting: a mano","anim_t_sonopull":"Compak® Sporting: {term}","anim_t_early":"Fucile già imbracciato alla chiamata","anim_s_in_time":"Il piattello parte {n} s dopo il segnale: in tempo (il limite è {max} s).","anim_s_late":"Il piattello parte {n} s dopo il segnale, oltre {max} s: l'arbitro chiama «No bird» e il piattello viene rilanciato.","anim_s_manual":"Lancio a mano: il piattello parte {n} s dopo la chiamata (consentito: da 0 a {max} s).","anim_s_sonopull":"Phonopull: il microfono sente la chiamata e il piattello parte {n} s dopo, ogni volta.","anim_s_gun_low":"Fucile sbracciato: il calcio tocca il corpo sotto la linea sul giubbotto.","anim_s_gun_mount":"Il piattello è apparso: solo ora il fucile sale alla spalla.","anim_s_early":"Chiamata con il fucile già imbracciato: la prima volta, un richiamo verbale e il cartellino giallo.","anim_s_click":"Clic: il colpo non è partito.","anim_s_hold":"Resta fermo: fucile chiuso e puntato verso il campo; non aprirlo e non toccare la sicura.","anim_s_ref":"L'arbitro controlla il fucile.","anim_s_repeat":"Primo malfunzionamento della serie: il piattello viene rilanciato.","anim_stop":"Ferma","anim_s_mount_ready":"Pronto: il fucile è basso, gli occhi aspettano il piattello.","anim_s_move":"Movimento: la mano avanti porta le canne sulla linea del piattello.","anim_s_mount":"Imbracciata: il calcio sale alla guancia e alla spalla; la testa resta ferma.","anim_s_shoot":"Sparo: l'imbracciata si completa insieme allo sparo.","anim_scale":"Solo il tiratore e la pedana sono in scala; il campo e il volo del piattello sono accorciati.","anim_cheek":"guancia sul nasello","anim_l_foot":"piede avanti","anim_l_body":"busto"},"cs":{"launch":"Vypustit","method":"Metoda","speed":"Rychlost terče","distance":"Vzdálenost","demo":"Ukázka metody","try":"Teď vy: stiskněte ve chvíli, kdy byste vystřelili","shoot":"Výstřel","hit":"Zásah! Terč se rozbil.","behind":"Za terčem – broky prošly za terčem","ahead":"Před terčem – broky prošly před terčem","perceived":"Předsazení, které vidíte v okamžiku rozhodnutí","actual":"Skutečné předsazení v okamžiku výstřelu","lab_note":"Zpomalený záběr a zjednodušená fyzika pro výuku. Broky za letu zpomalují: v průměru asi 330 m/s na 15 m, 300 m/s na 25 m a 255 m/s na 40 m (z hlavně vylétají rychlostí asi 360–430 m/s). Od rozhodnutí k výstřelu uplyne asi 0,15 s (průměrný odhad). Kruh označuje část střelového obrazce dost hustou, aby terč rozbila: poloměr asi 33 cm na 15 m a 45 cm na 40 m. Ústí hlavně je asi 1 m od oka. Vzdálenosti podél dráhy letu terče, předsazení a kruh jsou v měřítku; terč je nakreslen větší než ve skutečnosti, aby byl vidět (přibližně v měřítku tam, kde se předsazení počítá v šířkách terče). Skutečné předsazení závisí na rychlosti, vzdálenosti a úhlu terče, na náboji a na střelci.","unit_m":"m","unit_ft":"ft","unit_ms":"m/s","pair_report":"{term}: druhý terč vyletí na zvuk první rány","pair_sim":"{term}: oba terče vyletí zároveň","pair_rafale":"{term}: druhý terč ze stejné vrhačky, jakmile se znovu nabije","listen":"Poslechnout","no_shot":"Žádný výstřel.","at_muzzle":"viděno u ústí hlavně","compare":"Stejný terč, čtyři metody: skutečné předsazení je stejné, viděné ne","how_maintained":"Hlavně čekají před terčem a terč se k nim přibližuje. Stiskněte „Výstřel“, když odstup vypadá správně: zbraň se pak pohybuje rychlostí terče a toto předsazení drží.","how_swing":"Hlavně startují za terčem a jsou rychlejší než on. Stiskněte „Výstřel“, když hlavně míjejí přední okraj terče: během zpoždění zbraň dál získává náskok, proto je skutečné předsazení větší.","how_pullaway":"Hlavně nejdřív jdou s terčem, pak zrychlí dopředu. Stiskněte „Výstřel“, dokud zbraň ještě zrychluje: předsazení, které vidíte, je menší než skutečné.","how_ambush":"Hlavně stojí v bodě před terčem. Stiskněte „Výstřel“ dřív, než terč do toho bodu doletí: broky potřebují čas, a výstřel ve chvíli, kdy terč přiletí, jde za terč.","stop_gun":"Zastavit zbraň při výstřelu (chyba)","clay_widths":"šířek terče","unit_cm":"cm","unit_in":"palce","anim_play":"Přehrát","anim_replay":"Znovu","anim_slow":"Zpomaleně","anim_marker":"s animací","anim_h_flight":"Podívejte se, jak terč letí","anim_h_points":"Podívejte se na tři body","anim_h_eyes":"Podívejte se, kam se dívají oči","anim_h_stance":"Podívejte se na postoj","anim_h_pair":"Podívejte se, jak se vrhá dvojstřel","anim_h_lead":"Podívejte se, jak funguje předsazení","anim_h_mount":"Podívejte se na zalícení","anim_h_follow":"Podívejte se na dotažení švihu","anim_h_call":"Podívejte se na zavolání a vypuštění terče","anim_h_gunpos":"Podívejte se na polohu zbraně","anim_h_misfire":"Podívejte se, co dělat, když zbraň nevystřelí","anim_w_flight":"Sledujte celý let: odkud terč letí, kde ho dobře vidíte a kam míří.","anim_w_points":"Oči čekají v bodě zachycení terče, hlavně v bodě držení zbraně; terč se rozbije v místě zásahu.","anim_w_eyes":"Měkké zaostření kolem bodu zachycení terče, pak ostré zaostření na přední okraj terče.","anim_w_stance":"Přední noha míří k místu zásahu; trup se natáčí zpět k bodu držení zbraně.","anim_w_pair":"Sledujte, kdy vyletí druhý terč: po výstřelu, spolu s prvním, nebo ze stejné vrhačky.","anim_w_lead":"Sledujte mezeru mezi hlavněmi a terčem ve chvíli výstřelu a pak to zkuste sami.","anim_w_mount":"Hlavně se nejdřív pohybují s terčem; zalícení končí současně s výstřelem.","anim_w_follow":"Zbraň se po výstřelu dál pohybuje; když ji při výstřelu zastavíte, broky půjdou za terč.","anim_w_call":"Hodiny ukazují, kdy terč vyletí po zavolání nebo po signálu rozhodčího; opožděný terč je nový terč (No Bird).","anim_w_gunpos":"Ve Sporting™ zůstává pažba pod čárou na vestě, dokud se neobjeví terč.","anim_w_misfire":"Když zbraň nevystřelí, zůstaňte stát: zbraň zavřená a mířící do prostoru střelby, dokud ji rozhodčí neprohlédne.","anim_unit_s":"s","anim_after_call":"po zavolání","anim_after_signal":"po signálu","anim_t_signal":"Sporting™: signál rozhodčího","anim_t_late":"Opožděný terč","anim_t_manual":"Compak® Sporting: ručně","anim_t_sonopull":"Compak® Sporting: {term}","anim_t_early":"Zbraň už nahoře při zavolání","anim_s_in_time":"Terč vyletí {n} s po signálu: včas (limit je {max} s).","anim_s_late":"Terč vyletí {n} s po signálu, později než za {max} s: rozhodčí vyhlásí „No Bird“ a terč se vrhne znovu.","anim_s_manual":"Ruční vypuštění: terč vyletí {n} s po zavolání (povoleno je 0 až {max} s).","anim_s_sonopull":"Fonický systém: mikrofon uslyší zavolání a terč vyletí pokaždé {n} s poté.","anim_s_gun_low":"Pohotovostní postoj: pažba se dotýká těla pod čárou na vestě.","anim_s_gun_mount":"Terč se objevil: teprve teď jde zbraň k rameni.","anim_s_early":"Zavolání s už zalícenou zbraní: poprvé ústní napomenutí a žlutá karta.","anim_s_click":"Cvak: zbraň nevystřelila.","anim_s_hold":"Zůstaňte stát: zbraň zavřená a mířící do prostoru střelby; neotvírejte ji a nesahejte na pojistku.","anim_s_ref":"Rozhodčí zbraň prohlíží.","anim_s_repeat":"První porucha v položce: terč se vrhne znovu.","anim_stop":"Zastavit","anim_s_mount_ready":"Připraven: zbraň je dole, oči čekají na terč.","anim_s_move":"Pohyb: přední ruka vede hlavně po dráze terče.","anim_s_mount":"Zalícení: pažba jde k tváři a do ramene; hlava zůstává klidná.","anim_s_shoot":"Výstřel: zalícení končí současně s výstřelem.","anim_scale":"V měřítku je jen střelec a střelecké stanoviště; prostor střelby a let terče jsou zkrácené.","anim_cheek":"tvář na lícnici","anim_l_foot":"přední noha","anim_l_body":"trup"},"pl":{"launch":"Wyrzuć","method":"Metoda","speed":"Prędkość rzutka","distance":"Odległość","demo":"Zobacz metodę","try":"Twoja kolej: naciśnij, gdy oddałbyś strzał","shoot":"Strzał","hit":"Trafiony! Rzutek pęka.","behind":"Za rzutkiem — śrut przeszedł za rzutkiem","ahead":"Przed rzutkiem — śrut przeszedł przed rzutkiem","perceived":"Wyprzedzenie widziane w chwili decyzji","actual":"Rzeczywiste wyprzedzenie w chwili strzału","lab_note":"Zwolnione tempo, uproszczona fizyka do nauki. Śrut zwalnia w locie: średnio ok. 330 m/s na 15 m, 300 m/s na 25 m i 255 m/s na 40 m (z lufy wylatuje z prędkością ok. 360–430 m/s). Od decyzji do strzału mija ok. 0,15 s (szacunkowa średnia). Pierścień oznacza część snopa śrutu na tyle gęstą, by rozbić rzutek: promień ok. 33 cm na 15 m i 45 cm na 40 m. Wylot lufy jest ok. 1 m od oka. Odległości wzdłuż toru lotu rzutka, wyprzedzenie i pierścień są w skali; rzutek jest narysowany większy niż w rzeczywistości, żeby było go widać (mniej więcej w skali tam, gdzie wyprzedzenie liczy się w szerokościach rzutka). Rzeczywiste wyprzedzenie zależy od prędkości, odległości i kąta lotu rzutka, od naboju i od strzelca.","unit_m":"m","unit_ft":"ft","unit_ms":"m/s","pair_report":"{term}: drugi rzutek wylatuje na huk pierwszego strzału","pair_sim":"{term}: oba rzutki wylatują jednocześnie","pair_rafale":"{term}: drugi rzutek z tej samej wyrzutni, gdy tylko się przeładuje","listen":"Posłuchaj","no_shot":"Nie oddano strzału.","at_muzzle":"widziane u wylotu lufy","compare":"Ten sam rzutek, cztery metody: rzeczywiste wyprzedzenie jest takie samo, widziane – nie","how_maintained":"Lufy czekają przed rzutkiem, a rzutek się do nich zbliża. Naciśnij „Strzał”, gdy odstęp wygląda dobrze: broń porusza się wtedy z prędkością rzutka i utrzymuje to wyprzedzenie.","how_swing":"Lufy startują za rzutkiem i poruszają się szybciej od niego. Naciśnij „Strzał”, gdy lufy mijają przednią krawędź rzutka: w czasie opóźnienia broń dalej zyskuje, więc rzeczywiste wyprzedzenie jest większe.","how_pullaway":"Lufy najpierw idą razem z rzutkiem, potem przyspieszają do przodu. Naciśnij „Strzał”, póki broń jeszcze przyspiesza: widziane wyprzedzenie jest mniejsze od rzeczywistego.","how_ambush":"Lufy czekają nieruchomo w punkcie przed rzutkiem. Naciśnij „Strzał”, zanim rzutek dotrze do tego punktu: śrut potrzebuje czasu, więc strzał w chwili, gdy rzutek już tam jest, idzie za rzutkiem.","stop_gun":"Zatrzymaj broń przy strzale (błąd)","clay_widths":"szerokości rzutka","unit_cm":"cm","unit_in":"cala","anim_play":"Odtwórz","anim_replay":"Jeszcze raz","anim_slow":"Zwolnione tempo","anim_marker":"z animacją","anim_h_flight":"Zobacz, jak leci rzutek","anim_h_points":"Zobacz trzy punkty","anim_h_eyes":"Zobacz, gdzie patrzą oczy","anim_h_stance":"Zobacz postawę","anim_h_pair":"Zobacz, jak wyrzucany jest dublet","anim_h_lead":"Zobacz, jak działa wyprzedzenie","anim_h_mount":"Zobacz złożenie się do strzału","anim_h_follow":"Zobacz prowadzenie broni po strzale","anim_h_call":"Zobacz komendę i wyrzut rzutka","anim_h_gunpos":"Zobacz położenie broni","anim_h_misfire":"Zobacz, co zrobić, gdy broń nie wystrzeli","anim_w_flight":"Śledź cały lot: skąd leci rzutek, gdzie dobrze go widać i dokąd zmierza.","anim_w_points":"Oczy czekają w punkcie podjęcia rzutka, lufy w punkcie wyjściowym; rzutek pęka w punkcie strzału.","anim_w_eyes":"Miękkie skupienie wzroku wokół punktu podjęcia, potem twarde skupienie na przedniej krawędzi rzutka.","anim_w_stance":"Przednia stopa wskazuje punkt strzału; tułów obraca się z powrotem do punktu wyjściowego lufy.","anim_w_pair":"Zobacz, kiedy wylatuje drugi rzutek: po strzale, razem z pierwszym albo z tej samej wyrzutni.","anim_w_lead":"Patrz na odstęp między lufami a rzutkiem w chwili strzału, a potem spróbuj sam.","anim_w_mount":"Najpierw lufy ruszają za rzutkiem; złożenie kończy się razem ze strzałem.","anim_w_follow":"Broń porusza się dalej po strzale; jeśli zatrzymasz ją przy strzale, śrut przejdzie za rzutkiem.","anim_w_call":"Zegar pokazuje, kiedy rzutek wylatuje po komendzie lub sygnale sędziego; spóźniony rzutek to NO BIRD.","anim_w_gunpos":"W Sporting™ kolba pozostaje poniżej linii na kamizelce, dopóki nie pojawi się rzutek.","anim_w_misfire":"Gdy broń nie wystrzeli, zostań na miejscu: broń zamknięta i skierowana w stronę pola, dopóki sędzia jej nie obejrzy.","anim_unit_s":"s","anim_after_call":"po komendzie","anim_after_signal":"po sygnale","anim_t_signal":"Sporting™: sygnał sędziego","anim_t_late":"Spóźniony rzutek","anim_t_manual":"Compak® Sporting: ręcznie","anim_t_sonopull":"Compak® Sporting: {term}","anim_t_early":"Broń już w górze przy komendzie","anim_s_in_time":"Rzutek wylatuje {n} s po sygnale: na czas (limit to {max} s).","anim_s_late":"Rzutek wylatuje {n} s po sygnale, później niż po {max} s: sędzia ogłasza „No Bird” i rzutek jest wyrzucany ponownie.","anim_s_manual":"Wyrzut ręczny: rzutek wylatuje {n} s po komendzie (dozwolone od 0 do {max} s).","anim_s_sonopull":"Sonopull: mikrofon słyszy komendę i rzutek wylatuje {n} s później, za każdym razem.","anim_s_gun_low":"Pozycja gotowości: kolba dotyka ciała poniżej linii na kamizelce.","anim_s_gun_mount":"Rzutek się pojawił: dopiero teraz broń idzie do ramienia.","anim_s_early":"Komenda z bronią już złożoną: za pierwszym razem ustne upomnienie i żółta kartka.","anim_s_click":"Klik: broń nie wystrzeliła.","anim_s_hold":"Zostań na miejscu: broń zamknięta i skierowana w stronę pola; nie otwieraj jej i nie dotykaj bezpiecznika.","anim_s_ref":"Sędzia ogląda broń.","anim_s_repeat":"Pierwsza awaria w serii: rzutek jest wyrzucany ponownie.","anim_stop":"Zatrzymaj","anim_s_mount_ready":"Gotowość: broń jest nisko, oczy czekają na rzutek.","anim_s_move":"Ruch: przednia ręka prowadzi lufy wzdłuż toru rzutka.","anim_s_mount":"Złożenie: kolba idzie do policzka i do ramienia; głowa pozostaje nieruchoma.","anim_s_shoot":"Strzał: złożenie kończy się razem ze strzałem.","anim_scale":"W skali są tylko strzelec i stanowisko; pole i lot rzutka są skrócone.","anim_cheek":"policzek na grzbiecie kolby","anim_l_foot":"przednia stopa","anim_l_body":"tułów"},"pt":{"launch":"Lançar","method":"Método","speed":"Velocidade do prato","distance":"Distância","demo":"Ver o método","try":"A sua vez: carregue quando dispararia","shoot":"Disparar","hit":"Acertou! O prato parte-se.","behind":"Atrás — o chumbo passou atrás do prato","ahead":"À frente — o chumbo passou à frente do prato","perceived":"Avanço que vê no momento da decisão","actual":"Avanço real no momento do disparo","lab_note":"Câmara lenta e física simplificada para fins didáticos. O chumbo abranda em voo: em média cerca de 330 m/s em 15 m, 300 m/s em 25 m e 255 m/s em 40 m (sai do cano a cerca de 360–430 m/s). Da decisão ao disparo passam cerca de 0,15 s (uma estimativa média). O anel marca a parte do padrão de chumbo densa o suficiente para partir o prato: um raio de cerca de 33 cm a 15 m e 45 cm a 40 m. A boca do cano fica a cerca de 1 m do olho. As distâncias ao longo da trajetória do prato, o avanço e o anel estão à escala; o prato está desenhado maior do que é para que o possa ver (aproximadamente à escala onde o avanço se conta em larguras de prato). O avanço real depende da velocidade, da distância e do ângulo do prato, do cartucho e do atirador.","unit_m":"m","unit_ft":"pés","unit_ms":"m/s","pair_report":"{term}: o 2.º prato é lançado ao som do 1.º tiro","pair_sim":"{term}: os dois pratos são lançados ao mesmo tempo","pair_rafale":"{term}: o 2.º prato sai da mesma máquina logo que esta recarrega","listen":"Ouvir","no_shot":"Nenhum disparo.","at_muzzle":"visto na boca do cano","compare":"O mesmo prato, quatro métodos: o avanço real é o mesmo, o que vê não","how_maintained":"Os canos esperam à frente do prato, que se aproxima. Carregue em «Disparar» quando a distância parecer certa: a arma passa a mover-se à velocidade do prato e mantém esse avanço.","how_swing":"Os canos partem de trás do prato e movem-se mais depressa do que ele. Carregue em «Disparar» quando os canos passam a frente do prato: durante o atraso, a arma continua a ganhar terreno, por isso o avanço real é maior.","how_pullaway":"Os canos acompanham primeiro o prato e depois aceleram para a frente. Carregue em «Disparar» enquanto a arma ainda acelera: o avanço que vê é menor do que o real.","how_ambush":"Os canos esperam parados num ponto à frente do prato. Carregue em «Disparar» antes de o prato chegar a esse ponto: o chumbo precisa de tempo, e um disparo feito quando o prato chega passa atrás.","stop_gun":"Parar a arma no disparo (erro)","clay_widths":"larguras de prato","unit_cm":"cm","unit_in":"pol.","anim_play":"Reproduzir","anim_replay":"Ver de novo","anim_slow":"Câmara lenta","anim_marker":"com animação","anim_h_flight":"Veja como voa o prato","anim_h_points":"Veja os três pontos","anim_h_eyes":"Veja para onde vai o olhar","anim_h_stance":"Veja a posição dos pés","anim_h_pair":"Veja como é lançado um double","anim_h_lead":"Veja como funciona o avanço","anim_h_mount":"Veja como se põe a arma à cara","anim_h_follow":"Veja o acompanhamento","anim_h_call":"Veja o pedido do prato e o lançamento","anim_h_gunpos":"Veja a posição da arma","anim_h_misfire":"Veja o que fazer quando a arma não dispara","anim_w_flight":"Siga o voo todo: de onde vem o prato, onde o vê bem e para onde vai.","anim_w_points":"Os olhos esperam no ponto de visão, os canos no ponto de espera; o prato parte no ponto de tiro.","anim_w_eyes":"Foco suave à volta do ponto de visão, depois foco intenso no bordo da frente do prato.","anim_w_stance":"O pé da frente aponta para o ponto de tiro; o tronco roda para trás até ao ponto de espera.","anim_w_pair":"Veja quando sai o segundo prato: depois do tiro, junto com o primeiro ou da mesma máquina.","anim_w_lead":"Observe a distância entre os canos e o prato no momento do tiro e depois experimente.","anim_w_mount":"Primeiro os canos acompanham o prato; a arma só fica à cara no momento do tiro.","anim_w_follow":"A arma continua a mover-se depois do tiro; se a parar no disparo, o chumbo passa atrás.","anim_w_call":"O relógio mostra quando sai o prato depois do pedido ou do sinal do árbitro; um prato atrasado é NULO (No Bird).","anim_w_gunpos":"No Sporting™ a coronha fica abaixo da linha do colete até o prato aparecer.","anim_w_misfire":"Quando a arma não dispara, fique no lugar: arma fechada e apontada para o campo até o árbitro a examinar.","anim_unit_s":"s","anim_after_call":"depois do pedido","anim_after_signal":"depois do sinal","anim_t_signal":"Sporting™: sinal do árbitro","anim_t_late":"Prato atrasado","anim_t_manual":"Compak® Sporting: à mão","anim_t_sonopull":"Compak® Sporting: {term}","anim_t_early":"Arma já à cara no pedido","anim_s_in_time":"O prato sai {n} s depois do sinal: a tempo (o limite é {max} s).","anim_s_late":"O prato sai {n} s depois do sinal, mais de {max} s: o árbitro declara «No Bird» (NULO) e o prato é lançado de novo.","anim_s_manual":"Lançamento à mão: o prato sai {n} s depois do pedido (permitido: de 0 a {max} s).","anim_s_sonopull":"Phono-pull: o microfone ouve o pedido e o prato sai sempre {n} s depois.","anim_s_gun_low":"Arma em baixo: a coronha toca no corpo abaixo da linha do colete.","anim_s_gun_mount":"O prato apareceu: só agora a arma sobe ao ombro.","anim_s_early":"Pedido com a arma já à cara: da primeira vez, advertência verbal e cartão amarelo.","anim_s_click":"Clique: a arma não disparou.","anim_s_hold":"Fique no lugar: arma fechada e apontada para o campo; não a abra nem toque na patilha de segurança.","anim_s_ref":"O árbitro examina a arma.","anim_s_repeat":"Primeira avaria da série: o prato é lançado de novo.","anim_stop":"Parar","anim_s_mount_ready":"Pronto: a arma está em baixo e os olhos esperam pelo prato.","anim_s_move":"Mover: a mão da frente leva os canos ao longo da linha do prato.","anim_s_mount":"À cara: a coronha sobe à face e ao ombro; a cabeça fica imóvel.","anim_s_shoot":"Tiro: a arma só fica à cara no momento do tiro.","anim_scale":"Só o atirador e o posto de tiro estão à escala; o campo e o voo do prato estão encurtados.","anim_cheek":"face na crista","anim_l_foot":"pé da frente","anim_l_body":"tronco"},"hu":{"launch":"Indítás","method":"Módszer","speed":"Korongsebesség","distance":"Távolság","demo":"Nézd meg a módszert","try":"Te jössz: nyomd meg, amikor lőnél","shoot":"Lövés","hit":"Találat! A korong eltörik.","behind":"Mögötte – a sörét a korong mögött ment el","ahead":"Előtte – a sörét a korong előtt ment el","perceived":"A döntéskor látott elétartás","actual":"Valós elétartás a lövés pillanatában","lab_note":"Lassítás, a tanításhoz egyszerűsített fizika. A sörét repülés közben lassul: átlagosan kb. 330 m/s 15 m-en, 300 m/s 25 m-en és 255 m/s 40 m-en (a csövet kb. 360–430 m/s sebességgel hagyja el). A döntéstől a lövésig kb. 0,15 s telik el (átlagos becslés). A gyűrű a sörétkép azon részét jelöli, amely elég sűrű a korong széttöréséhez: sugara kb. 33 cm 15 m-en és 45 cm 40 m-en. A csőtorkolat kb. 1 m-re van a szemtől. A korong röppályája menti távolságok, az elétartás és a gyűrű méretarányosak; a korong a valóságosnál nagyobbra van rajzolva, hogy látható legyen (nagyjából méretarányos ott, ahol az elétartást korongszélességben számoljuk). A valós elétartás a korong sebességétől, távolságától és szögétől, a tölténytől és a lövésztől függ.","unit_m":"m","unit_ft":"láb","unit_ms":"m/s","pair_report":"{term}: a 2. korong az 1. lövés hangjára indul","pair_sim":"{term}: mindkét korong egyszerre indul","pair_rafale":"{term}: a 2. korong ugyanabból a gépből, amint a gép újratöltött","listen":"Meghallgatás","no_shot":"Nem volt lövés.","at_muzzle":"a csőtorkolatnál nézve","compare":"Ugyanaz a korong, négy módszer: a valós elétartás ugyanaz, a látott nem","how_maintained":"A csövek a korong előtt várnak, a korong közeledik hozzájuk. Nyomd meg a „Lövés” gombot, amikor a távolság jónak látszik: ekkor a puska a korong sebességével halad, és tartja ezt az elétartást.","how_swing":"A csövek a korong mögül indulnak, és gyorsabbak nála. Nyomd meg a „Lövés” gombot, amikor a csövek elhagyják a korong elejét: a késleltetés alatt a puska tovább előz, ezért a valós elétartás nagyobb.","how_pullaway":"A csövek előbb a koronggal együtt mennek, aztán előre gyorsulnak. Nyomd meg a „Lövés” gombot, amíg a puska még gyorsul: a látott elétartás kisebb a valósnál.","how_ambush":"A csövek mozdulatlanul várnak egy ponton a korong előtt. Nyomd meg a „Lövés” gombot, mielőtt a korong odaér: a sörétnek idő kell, így ha akkor lősz, amikor a korong már ott van, a lövés mögé megy.","stop_gun":"A puska megállítása lövéskor (hiba)","clay_widths":"korongszélesség","unit_cm":"cm","unit_in":"hüvelyk","anim_play":"Lejátszás","anim_replay":"Újra","anim_slow":"Lassítás","anim_marker":"animációval","anim_h_flight":"Nézd meg, hogyan repül a korong","anim_h_points":"Nézd meg a három pontot","anim_h_eyes":"Nézd meg, hová néz a szem","anim_h_stance":"Nézd meg a beállást","anim_h_pair":"Nézd meg, hogyan indul egy dublé","anim_h_lead":"Nézd meg, hogyan működik az elétartás","anim_h_mount":"Nézd meg a vállba vételt","anim_h_follow":"Nézd meg az elkísérést","anim_h_call":"Nézd meg a korong kérését és indítását","anim_h_gunpos":"Nézd meg a fegyver helyzetét","anim_h_misfire":"Nézd meg, mi a teendő, ha a lövés elmarad","anim_w_flight":"Kövesd az egész röppályát: honnan jön a korong, hol látod jól, és merre megy.","anim_w_points":"A szem a korongfelvételi ponton vár, a csövek a fegyvertartási ponton; a korong a lövési ponton törik.","anim_w_eyes":"Laza fókusz a korongfelvételi pont körül, aztán éles fókusz a korong elülső szélén.","anim_w_stance":"Az elülső láb a lövési pontra mutat; a test visszafordul a fegyvertartási pontig.","anim_w_pair":"Figyeld, mikor indul a második korong: a lövés után, az elsővel együtt vagy ugyanabból a gépből.","anim_w_lead":"Figyeld a csövek és a korong közti távolságot a lövés pillanatában, aztán próbáld ki te is.","anim_w_mount":"Először a csövek indulnak a koronggal; a vállba vétel a lövéssel együtt fejeződik be.","anim_w_follow":"A fegyver a lövés után is mozog; ha lövéskor megállítod, a sörét mögé megy.","anim_w_call":"Az óra mutatja, mikor indul a korong a kérés vagy a bíró jele után; a késve induló korong „No bird”.","anim_w_gunpos":"A Sporting™-ban a tus a mellényen lévő jelölővonal alatt marad, amíg a korong meg nem jelenik.","anim_w_misfire":"Ha a lövés elmarad, maradj a helyeden: a fegyver zárva, a lőtér felé mutat, amíg a bíró meg nem vizsgálja.","anim_unit_s":"mp","anim_after_call":"a kérés után","anim_after_signal":"a jel után","anim_t_signal":"Sporting™: a bíró jele","anim_t_late":"Késve induló korong","anim_t_manual":"Compak® Sporting: kézzel","anim_t_sonopull":"Compak® Sporting: {term}","anim_t_early":"Fegyver már vállban a kéréskor","anim_s_in_time":"A korong a jel után {n} mp múlva indul: időben (a határ {max} mp).","anim_s_late":"A korong a jel után {n} mp múlva indul, később, mint {max} mp: a bíró bemondja, hogy „No bird”, és a korongot újra dobják.","anim_s_manual":"Kézi indítás: a korong a kérés után {n} mp múlva indul (megengedett: 0–{max} mp).","anim_s_sonopull":"Hangvezérlés: a mikrofon meghallja a kérést, és a korong mindig {n} mp múlva indul.","anim_s_gun_low":"Készenléti testhelyzet: a tus a mellényen lévő vonal alatt érinti a testet.","anim_s_gun_mount":"Megjelent a korong: csak most kerül a fegyver a vállba.","anim_s_early":"Kérés már vállba vett fegyverrel: első alkalommal szóbeli figyelmeztetés és sárga lap.","anim_s_click":"Kattanás: a fegyver nem sült el.","anim_s_hold":"Maradj a helyeden: a fegyver zárva, a lőtér felé mutat; ne nyisd ki, és ne nyúlj a biztosítóhoz.","anim_s_ref":"A bíró megvizsgálja a fegyvert.","anim_s_repeat":"A kör első hibája: a korongot újra dobják.","anim_stop":"Leállítás","anim_s_mount_ready":"Készen: a fegyver lent van, a szem a korongra vár.","anim_s_move":"Mozdulat: az elülső kéz a korong vonalán indítja a csöveket.","anim_s_mount":"Vállba vétel: a tus az archoz és a vállba kerül; a fej mozdulatlan marad.","anim_s_shoot":"Lövés: a vállba vétel a lövéssel együtt fejeződik be.","anim_scale":"Csak a lövész és a lőállás méretarányos; a lőtér és a korong röppályája rövidítve látható.","anim_cheek":"arc a pofadékon","anim_l_foot":"elülső láb","anim_l_body":"test"},"fi":{"launch":"Lähetä","method":"Menetelmä","speed":"Kiekon nopeus","distance":"Etäisyys","demo":"Katso menetelmä","try":"Sinun vuorosi: paina, kun ampuisit","shoot":"Ammu","hit":"Osuma! Kiekko hajoaa.","behind":"Takana – laukaus meni kiekon taakse","ahead":"Edessä – laukaus meni kiekon edelle","perceived":"Ennakko, jonka näet päätöshetkellä","actual":"Todellinen ennakko laukaushetkellä","lab_note":"Hidastettu, opetusta varten yksinkertaistettu fysiikka. Haulit hidastuvat lennossa: keskimäärin noin 330 m/s 15 metrin, 300 m/s 25 metrin ja 255 m/s 40 metrin matkalla (piipusta ne lähtevät noin 360–430 m/s nopeudella). Päätöksestä laukaukseen kuluu noin 0,15 s (keskimääräinen arvio). Rengas merkitsee sitä hauliparven osaa, joka on tarpeeksi tiheä rikkomaan kiekon: säde noin 33 cm 15 metrissä ja 45 cm 40 metrissä. Piipun suu on noin 1 m:n päässä silmästä. Etäisyydet kiekon lentolinjalla, ennakko ja rengas ovat mittakaavassa; kiekko on piirretty todellista suuremmaksi, jotta se näkyy (suunnilleen mittakaavassa siellä, missä ennakko lasketaan kiekon leveyksinä). Todellinen ennakko riippuu kiekon nopeudesta, etäisyydestä ja kulmasta, patruunasta ja ampujasta.","unit_m":"m","unit_ft":"ft","unit_ms":"m/s","pair_report":"{term}: 2. kiekko lähtee 1. laukauksen äänestä","pair_sim":"{term}: molemmat kiekot lähtevät yhdessä","pair_rafale":"{term}: 2. kiekko samasta heittimestä heti, kun heitin on latautunut","listen":"Kuuntele","no_shot":"Laukausta ei ammuttu.","at_muzzle":"piipun suulla nähtynä","compare":"Sama kiekko, neljä menetelmää: todellinen ennakko on sama, nähty ei","how_maintained":"Piiput odottavat kiekon edessä, ja kiekko lähestyy niitä. Paina ”Ammu”, kun väli näyttää oikealta: ase liikkuu sen jälkeen kiekon nopeudella ja pitää tämän ennakon.","how_swing":"Piiput lähtevät kiekon takaa ja liikkuvat sitä nopeammin. Paina ”Ammu”, kun piiput ohittavat kiekon etureunan: viiveen aikana ase etenee yhä, joten todellinen ennakko on suurempi.","how_pullaway":"Piiput seuraavat ensin kiekkoa ja kiihdyttävät sitten sen eteen. Paina ”Ammu”, kun ase vielä kiihtyy: näkemäsi ennakko on todellista pienempi.","how_ambush":"Piiput odottavat paikallaan pisteessä kiekon edessä. Paina ”Ammu” ennen kuin kiekko saapuu pisteeseen: haulit tarvitsevat aikaa, joten laukaus kiekon saapuessa menee taakse.","stop_gun":"Pysäytä ase laukaisussa (virhe)","clay_widths":"kiekon leveyttä","unit_cm":"cm","unit_in":"tuumaa","anim_play":"Toista","anim_replay":"Uudelleen","anim_slow":"Hidastus","anim_marker":"animaation kanssa","anim_h_flight":"Katso, miten kiekko lentää","anim_h_points":"Katso kolme pistettä","anim_h_eyes":"Katso, minne silmät katsovat","anim_h_stance":"Katso ampuma-asento","anim_h_pair":"Katso, miten kaksoiskiekko heitetään","anim_h_lead":"Katso, miten ennakko toimii","anim_h_mount":"Katso aseen nosto","anim_h_follow":"Katso saatto","anim_h_call":"Katso kiekon pyytäminen ja lähtö","anim_h_gunpos":"Katso aseen asento","anim_h_misfire":"Katso, mitä tehdä, kun ase ei laukea","anim_w_flight":"Seuraa koko lentoa: mistä kiekko tulee, missä näet sen hyvin ja minne se menee.","anim_w_points":"Silmät odottavat katsepisteessä, piiput aloituskohdassa; kiekko hajoaa osumapisteessä.","anim_w_eyes":"Pehmeä katse katsepisteen ympärillä, sitten terävä katse kiekon etureunaan.","anim_w_stance":"Etujalka osoittaa osumapisteeseen; vartalo kiertyy takaisin aloituskohtaan.","anim_w_pair":"Katso, milloin toinen kiekko lähtee: laukauksen jälkeen, yhtä aikaa ensimmäisen kanssa vai samasta heittimestä.","anim_w_lead":"Katso piippujen ja kiekon väliä laukauksen hetkellä ja kokeile sitten itse.","anim_w_mount":"Ensin piiput lähtevät kiekon mukaan; nosto valmistuu samalla kun laukaus lähtee.","anim_w_follow":"Ase liikkuu vielä laukauksen jälkeen; jos pysäytät sen laukaisussa, haulit menevät taakse.","anim_w_call":"Kello näyttää, milloin kiekko lähtee pyynnön tai tuomarin merkin jälkeen; myöhässä lähtenyt kiekko on uusi kiekko (No Bird).","anim_w_gunpos":"Sporting™-lajissa tukki pysyy liivin merkkiviivan alapuolella, kunnes kiekko tulee näkyviin.","anim_w_misfire":"Kun ase ei laukea, pysy paikallasi: ase suljettuna ja ammuntasuuntaan, kunnes tuomari on tarkastanut sen.","anim_unit_s":"s","anim_after_call":"pyynnön jälkeen","anim_after_signal":"merkin jälkeen","anim_t_signal":"Sporting™: tuomarin merkki","anim_t_late":"Myöhässä lähtenyt kiekko","anim_t_manual":"Compak® Sporting: käsin","anim_t_sonopull":"Compak® Sporting: {term}","anim_t_early":"Ase jo poskella pyydettäessä","anim_s_in_time":"Kiekko lähtee {n} s merkin jälkeen: ajoissa (raja on {max} s).","anim_s_late":"Kiekko lähtee {n} s merkin jälkeen, myöhemmin kuin {max} s: tuomari huutaa ”No Bird”, ja kiekko heitetään uudelleen.","anim_s_manual":"Käsilähtö: kiekko lähtee {n} s pyynnön jälkeen (sallittu 0–{max} s).","anim_s_sonopull":"Mikrofonilähtö: mikrofoni kuulee pyynnön, ja kiekko lähtee joka kerta {n} s myöhemmin.","anim_s_gun_low":"Valmiusasento: tukki koskettaa vartaloa liivin merkkiviivan alapuolella.","anim_s_gun_mount":"Kiekko tuli näkyviin: vasta nyt ase nousee olkapäälle.","anim_s_early":"Pyyntö ase jo nostettuna: ensimmäisellä kerralla suullinen varoitus ja keltainen kortti.","anim_s_click":"Naksahdus: ase ei lauennut.","anim_s_hold":"Pysy paikallasi: ase suljettuna ja ammuntasuuntaan; älä avaa sitä äläkä koske varmistimeen.","anim_s_ref":"Tuomari tarkastaa aseen.","anim_s_repeat":"Kierroksen ensimmäinen asehäiriö: kiekko heitetään uudelleen.","anim_stop":"Pysäytä","anim_s_mount_ready":"Valmiina: ase on alhaalla, ja silmät odottavat kiekkoa.","anim_s_move":"Liike: etukäsi vie piiput kiekon lentolinjalle.","anim_s_mount":"Nosto: tukki nousee poskelle ja olkapäähän; pää pysyy paikallaan.","anim_s_shoot":"Laukaus: nosto valmistuu samalla kun laukaus lähtee.","anim_scale":"Vain ampuja ja ampumapaikka ovat mittakaavassa; kenttä ja kiekon lento on lyhennetty.","anim_cheek":"poski poskipakalla","anim_l_foot":"etujalka","anim_l_body":"vartalo"},"lt":{"launch":"Paleisti","method":"Metodas","speed":"Taikinio greitis","distance":"Atstumas","demo":"Žiūrėti metodą","try":"Jūsų eilė: spauskite tada, kai šautumėte","shoot":"Šauti","hit":"Pataikyta! Taikinys sudūžta.","behind":"Už taikinio — šratai praskriejo už taikinio","ahead":"Prieš taikinį — šratai praskriejo priekyje taikinio","perceived":"Pralenkimas, kurį matote sprendimo metu","actual":"Tikrasis pralenkimas šūvio metu","lab_note":"Sulėtintas vaizdas, mokymui supaprastinta fizika. Šratai skrisdami lėtėja: vidutiniškai apie 330 m/s per 15 m, 300 m/s per 25 m ir 255 m/s per 40 m (iš vamzdžio jie išlekia apie 360–430 m/s greičiu). Nuo sprendimo iki šūvio praeina apie 0,15 s (vidutinis įvertis). Žiedas žymi tą šratų pluošto dalį, kuri pakankamai tanki taikiniui sudaužyti: spindulys apie 33 cm ties 15 m ir 45 cm ties 40 m. Vamzdžio žiotys yra apie 1 m nuo akies. Atstumai išilgai taikinio skrydžio linijos, pralenkimas ir žiedas pavaizduoti pagal mastelį; taikinys nupieštas didesnis nei iš tikrųjų, kad būtų matomas (maždaug pagal mastelį ten, kur pralenkimas skaičiuojamas taikinio pločiais). Tikrasis pralenkimas priklauso nuo taikinio greičio, atstumo ir kampo, nuo šovinio ir šaulio.","unit_m":"m","unit_ft":"pėd.","unit_ms":"m/s","pair_report":"{term}: antrasis taikinys išlekia pirmojo šūvio garsu","pair_sim":"{term}: abu taikiniai išlekia kartu","pair_rafale":"{term}: antrasis taikinys iš tos pačios mašinėlės, kai tik ji persikrauna","listen":"Klausyti","no_shot":"Šūvio nebuvo.","at_muzzle":"matoma prie vamzdžio žiočių","compare":"Tas pats taikinys, keturi metodai: tikrasis pralenkimas vienodas, matomas – ne","how_maintained":"Vamzdžiai laukia priešais taikinį, o taikinys artėja prie jų. Spauskite „Šauti“, kai tarpas atrodo tinkamas: tada ginklas juda taikinio greičiu ir išlaiko šį pralenkimą.","how_swing":"Vamzdžiai pradeda už taikinio ir juda greičiau už jį. Spauskite „Šauti“, kai vamzdžiai praeina priekinį taikinio kraštą: per delsą ginklas dar pasistūmi į priekį, todėl tikrasis pralenkimas didesnis.","how_pullaway":"Vamzdžiai iš pradžių juda kartu su taikiniu, tada greitėja į priekį. Spauskite „Šauti“, kol ginklas dar greitėja: matomas pralenkimas mažesnis už tikrąjį.","how_ambush":"Vamzdžiai nejudėdami laukia taške priešais taikinį. Spauskite „Šauti“ anksčiau, nei taikinys pasieks tą tašką: šratams reikia laiko, todėl šūvis tą akimirką, kai taikinys atskrieja, nueina už jo.","stop_gun":"Sustabdyti ginklą šūvio metu (klaida)","clay_widths":"taikinio pločių","unit_cm":"cm","unit_in":"col.","anim_play":"Leisti","anim_replay":"Dar kartą","anim_slow":"Sulėtintai","anim_marker":"su animacija","anim_h_flight":"Pažiūrėkite, kaip skrenda taikinys","anim_h_points":"Pažiūrėkite į tris taškus","anim_h_eyes":"Pažiūrėkite, kur žiūri akys","anim_h_stance":"Pažiūrėkite į stovėseną","anim_h_pair":"Pažiūrėkite, kaip paleidžiamas dubletas","anim_h_lead":"Pažiūrėkite, kaip veikia pralenkimas","anim_h_mount":"Pažiūrėkite, kaip šautuvas atremiamas į petį","anim_h_follow":"Pažiūrėkite į palydėjimą","anim_h_call":"Pažiūrėkite į taikinio prašymą ir paleidimą","anim_h_gunpos":"Pažiūrėkite į šautuvo padėtį","anim_h_misfire":"Pažiūrėkite, ką daryti, kai šautuvas neiššauna","anim_w_flight":"Sekite visą skrydį: iš kur atskrenda taikinys, kur jį gerai matote ir kur jis skrenda.","anim_w_points":"Akys laukia taikinio pastebėjimo taške, vamzdžiai – ginklo laikymo taške; taikinys sudūžta sudaužymo taške.","anim_w_eyes":"Švelnus fokusavimas aplink pastebėjimo tašką, tada aštrus fokusavimas į priekinį taikinio kraštą.","anim_w_stance":"Priekinė koja nukreipta į sudaužymo tašką; liemuo pasisuka atgal į ginklo laikymo tašką.","anim_w_pair":"Stebėkite, kada išlekia antrasis taikinys: po šūvio, kartu su pirmuoju ar iš tos pačios mašinėlės.","anim_w_lead":"Stebėkite tarpą tarp vamzdžių ir taikinio šūvio akimirką, tada pabandykite patys.","anim_w_mount":"Pirmiausia vamzdžiai juda kartu su taikiniu; šautuvas atremiamas į petį kartu su šūviu.","anim_w_follow":"Šautuvas juda ir po šūvio; jei sustabdysite jį šaudami, šratai praeis už taikinio.","anim_w_call":"Laikrodis rodo, kada taikinys išlekia po prašymo ar teisėjo signalo; pavėlavęs taikinys – „No Bird“ (kartoti).","anim_w_gunpos":"Sporting™ rungtyje buožė lieka žemiau linijos ant liemenės, kol pasirodo taikinys.","anim_w_misfire":"Kai šautuvas neiššauna, likite vietoje: šautuvas uždarytas ir nukreiptas į šaudymo lauką, kol teisėjas jį apžiūrės.","anim_unit_s":"s","anim_after_call":"po prašymo","anim_after_signal":"po signalo","anim_t_signal":"Sporting™: teisėjo signalas","anim_t_late":"Pavėlavęs taikinys","anim_t_manual":"Compak® Sporting: rankiniu būdu","anim_t_sonopull":"Compak® Sporting: {term}","anim_t_early":"Šautuvas jau prie peties prašant","anim_s_in_time":"Taikinys išlekia praėjus {n} s po signalo: laiku (riba – {max} s).","anim_s_late":"Taikinys išlekia praėjus {n} s po signalo, vėliau nei per {max} s: teisėjas skelbia „No Bird“, ir taikinys paleidžiamas iš naujo.","anim_s_manual":"Rankinis paleidimas: taikinys išlekia praėjus {n} s po prašymo (leidžiama nuo 0 iki {max} s).","anim_s_sonopull":"Balso sistema: mikrofonas išgirsta prašymą, ir taikinys kaskart išlekia po {n} s.","anim_s_gun_low":"Parengties pozicija: buožė liečia kūną žemiau linijos ant liemenės.","anim_s_gun_mount":"Taikinys pasirodė: tik dabar šautuvas keliamas prie peties.","anim_s_early":"Prašymas su jau prie peties atremtu šautuvu: pirmą kartą – žodinis įspėjimas ir geltonoji kortelė.","anim_s_click":"Spragtelėjimas: šautuvas neiššovė.","anim_s_hold":"Likite vietoje: šautuvas uždarytas ir nukreiptas į šaudymo lauką; neatidarykite jo ir nelieskite saugiklio.","anim_s_ref":"Teisėjas apžiūri šautuvą.","anim_s_repeat":"Pirmasis gedimas serijoje: taikinys paleidžiamas iš naujo.","anim_stop":"Sustabdyti","anim_s_mount_ready":"Pasiruošus: šautuvas nuleistas, akys laukia taikinio.","anim_s_move":"Judesys: priekinė ranka veda vamzdžius taikinio linija.","anim_s_mount":"Atrėmimas: buožė kyla prie skruosto ir į petį; galva lieka nejudanti.","anim_s_shoot":"Šūvis: atrėmimas baigiamas kartu su šūviu.","anim_scale":"Pagal mastelį pavaizduoti tik šaulys ir šaudymo vieta; laukas ir taikinio skrydis sutrumpinti.","anim_cheek":"skruostas ant skruostinės atramos","anim_l_foot":"priekinė koja","anim_l_body":"liemuo"}};
